package com.aistock.notification.alert;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class AlertMarketUseMysqlTest {
 AlertEvaluationMysqlTest f;AlertMarketUseClient client;AlertMarketUseOwner uses;AlertEvaluationService service;AtomicReference<Instant> now;Clock clock;AlertRuleRepository repo;
 @BeforeEach void setup()throws Exception{f=new AlertEvaluationMysqlTest();f.setup();now=new AtomicReference<>(f.clock.instant());clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.get();}};repo=new AlertRuleRepository(f.jdbc);client=mock(AlertMarketUseClient.class);when(client.register(any())).thenAnswer(c->receipt());when(client.complete(any(),any())).thenAnswer(c->{var b=(AlertMarketUseClient.Receipt)c.getArgument(1);return new AlertMarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());});when(f.market.reference(f.evidence.id())).thenReturn(new AlertEvidenceClient.Reference(f.evidence.id(),"SH600030",f.evidence.rawVersionId()));uses=new AlertMarketUseOwner(repo,new ObjectMapper().findAndRegisterModules(),client,clock,true);service=new AlertEvaluationService(repo,f.market,f.accounts,new com.aistock.notification.alertmail.AlertMailOutbox(new com.aistock.notification.alertmail.AlertMailRepository(f.jdbc),false,Duration.ofHours(24)),clock,20,uses);}
 AlertMarketUseClient.Receipt receipt(){return new AlertMarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(f.evidence.rawVersionId().toString()));}
 @Test void commitsTriggerInboxOutboxBeforeNotifyAndReplayDoesNotReread(){var r=f.request();when(f.market.read(f.evidence.id())).thenAnswer(c->{assertEquals("ALERT_EVALUATION",AlertMarketUseContext.headers().get("X-Market-Use-Purpose"));assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return f.evidence;});doAnswer(c->{assertTrue(AlertMarketUseContext.headers().isEmpty());assertEquals(1,f.triggers());assertEquals(1,f.messages());assertEquals(1,f.jdbc.queryForObject("select count(*) from alert_mail_delivery where owner_id=?",Integer.class,f.owner.toString()));var b=(AlertMarketUseClient.Receipt)c.getArgument(1);return new AlertMarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());}).when(client).complete(any(),any());var done=service.evaluate(r);assertEquals("TRIGGERED",done.state());assertEquals(done,service.evaluate(r));assertEquals(done.triggerId().toString(),uses.proof(r.operationId(),"1").path("resultIdentity").asText());assertEquals(9,uses.proof(r.operationId(),"1").size());verify(f.market,times(1)).read(f.evidence.id());verify(f.market,times(1)).reference(f.evidence.id());verify(client,times(1)).register(any());}
 @Test void deniedNeverReadsContentAndWrongManifestNeverTriggers(){doThrow(AlertMarketUseClient.notReady()).when(client).requireReady();assertEquals("FAILED",service.evaluate(f.request()).state());verify(f.market,never()).read(any());verify(f.market,never()).boundary(any());assertEquals(0,f.triggers());assertEquals(0,f.messages());}
 @Test void evidenceMustMatchBoundRawBeforeAccountOrTrigger(){doReturn(new AlertMarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString()))).when(client).register(any());assertEquals("FAILED",service.evaluate(f.request()).state());assertEquals(0,f.triggers());verify(f.accounts,never()).context(any());assertTrue(AlertMarketUseContext.headers().isEmpty());}
 @Test void unknownPostRecoveryUsesSameRequestOnlyAndKeepsFailedEvaluation(){doThrow(AlertMarketUseClient.unavailable()).when(client).register(any());var r=f.request();assertEquals("FAILED",service.evaluate(r).state());var cap=org.mockito.ArgumentCaptor.forClass(AlertMarketUseClient.Request.class);verify(client).register(cap.capture());var original=cap.getValue();when(client.find(original)).thenReturn(Optional.of(receipt()));uses.recoverOne(r.operationId());verify(client,times(1)).register(any());verify(client).find(original);verify(f.market,times(1)).reference(any());verify(f.market,never()).read(any());assertEquals("FAILED",uses.proof(r.operationId(),"1").path("state").asText());assertTrue(f.jdbc.queryForObject("select completion_acked from alert_evaluation_market_use where operation_id=?",Boolean.class,r.operationId().toString()));}
 @Test void physicallyExpiredProofPreventsLateTriggerEvenAfterClockRollback(){var r=f.request();var store=new AlertEvaluationStore(repo,clock);assertTrue(store.begin(f.owner,r).dispatch());try(var scope=uses.acquire(f.owner,r,()->f.market.reference(r.evidenceId()))){}assertThrows(BusinessException.class,()->uses.proof(r.operationId(),"1"));now.set(r.leaseUntil().plusSeconds(1));var proof=uses.proof(r.operationId(),"1");assertEquals("FAILED",proof.path("state").asText());now.set(f.clock.instant());var done=service.evaluate(r);assertEquals("FAILED",done.state());assertEquals(proof,uses.proof(r.operationId(),"1"));assertEquals(0,f.triggers());verify(f.market,never()).read(any());assertThrows(BusinessException.class,()->uses.proof(r.operationId(),"2"));}
 @Test void failedOutboxRollsBackTriggerAndInboxBeforeFailedProof(){String name="use_outbox_"+f.owner.toString().replace("-","");f.jdbc.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON alert_mail_delivery FOR EACH ROW BEGIN IF NEW.owner_id='"+f.owner+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture reject'; END IF; END");try{var r=f.request();assertEquals("FAILED",service.evaluate(r).state());assertEquals(0,f.triggers());assertEquals(0,f.messages());assertEquals("FAILED",uses.proof(r.operationId(),"1").path("state").asText());}finally{f.jdbc.execute("DROP TRIGGER "+name);}}
 @Test void actualGuardLockWaitCannotProveOldRunningStateAfterExpiry()throws Exception{var r=f.request();var store=new AlertEvaluationStore(repo,clock);store.begin(f.owner,r);try(var scope=uses.acquire(f.owner,r,()->f.market.reference(r.evidenceId()))){}var pool=Executors.newSingleThreadExecutor();try(var lock=f.jdbc.getDataSource().getConnection()){lock.setAutoCommit(false);try(var q=lock.prepareStatement("select user_id from alert_user_guard where user_id=? for update")){q.setString(1,f.owner.toString());q.executeQuery().close();}var result=pool.submit(()->uses.proof(r.operationId(),"1"));long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);boolean waiting=false;while(System.nanoTime()<end){if(f.jdbc.queryForObject("select count(*) from performance_schema.data_lock_waits",Integer.class)>0){waiting=true;break;}Thread.sleep(10);}assertTrue(waiting);now.set(r.leaseUntil().plusSeconds(1));lock.commit();assertEquals("FAILED",result.get(4,TimeUnit.SECONDS).path("state").asText());assertEquals("FAILED",store.receipt(r.operationId()).state());}finally{pool.shutdownNow();}}
 @Test void newlyPublishedBoundaryStillSkipsOldEvidenceWithoutTrigger(){when(f.market.boundary("SH600030")).thenReturn(new AlertRecords.Boundary("SH600030","baostock",UUID.randomUUID(),f.evidence.tradeDate(),f.evidence.tradeDate(),f.evidence.tradeDate(),"a".repeat(64),clock.instant(),"alert-boundary-v1"));var r=f.request();assertEquals("SKIPPED_STALE",service.evaluate(r).state());assertEquals(0,f.triggers());assertEquals("SUCCEEDED",uses.proof(r.operationId(),"1").path("state").asText());var disabled=new AlertMarketUseOwner(repo,new ObjectMapper().findAndRegisterModules(),client,clock,false);assertEquals(uses.proof(r.operationId(),"1"),disabled.proof(r.operationId(),"1"));}

 @Test void delayedRegistrationPastOwnerLeaseNeverStartsEvidenceBodyRead(){var r=f.request();doAnswer(c->{now.set(r.leaseUntil().plusSeconds(1));return receipt();}).when(client).register(any());assertEquals("FAILED",service.evaluate(r).state());verify(f.market,never()).read(any());verify(f.accounts,never()).context(any());assertEquals(0,f.triggers());assertEquals("FAILED",uses.proof(r.operationId(),"1").path("state").asText());}

}
